import{_ as e,o as i,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Private Rooms","description":"","frontmatter":{},"headers":[],"relativePath":"gameplay/private_rooms.md","filePath":"gameplay/private_rooms.md","lastUpdated":1788364293000}'),t={name:"gameplay/private_rooms.md"};function l(n,a,s,d,c,h){return i(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="private-rooms" tabindex="-1">Private Rooms <a class="header-anchor" href="#private-rooms" aria-label="Permalink to &quot;Private Rooms&quot;">​</a></h1><h2 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to &quot;Explanation&quot;">​</a></h2><p>In Private Rooms players either play a normal Ranked Seed or they can choose a Set Seed. It is also possible to disable Seedtypes so players can practice the Seedtypes they want. There are 20+ Categories to choose from aside from the standard Any% Category and players can chooe which Rules to turn ON/OFF (QOL rules, experimental features and rules that make the game harder/easier(fairer).</p><h2 id="special-tiers" tabindex="-1">Special Tiers <a class="header-anchor" href="#special-tiers" aria-label="Permalink to &quot;Special Tiers&quot;">​</a></h2><p>Everyone can make a Private Room in the most basic form, but certain features require a <a href="https://store.mcsrranked.com/category/tiers" target="_blank" rel="noreferrer">Special Tier</a>. Here is specified what the different tiers can do in a Private Room.</p><h3 id="no-pickaxe" tabindex="-1">No Pickaxe <a class="header-anchor" href="#no-pickaxe" aria-label="Permalink to &quot;No Pickaxe&quot;">​</a></h3><ul><li>Max. 32 players</li><li>Toggle Rules ON/OFF</li><li>Run Command on World Join</li><li>Choose Category</li><li>Choose a Set Seed</li></ul><h3 id="stone-pickaxe" tabindex="-1">Stone Pickaxe <a class="header-anchor" href="#stone-pickaxe" aria-label="Permalink to &quot;Stone Pickaxe&quot;">​</a></h3><ul><li>Same as No Pickaxe</li><li>Solo Private Room</li><li>Choose Seedtype</li><li>Choose Bastiontype</li></ul><h3 id="iron-pickaxe" tabindex="-1">Iron Pickaxe <a class="header-anchor" href="#iron-pickaxe" aria-label="Permalink to &quot;Iron Pickaxe&quot;">​</a></h3><ul><li>Same as Stone Pickaxe</li><li>Max. 64 players</li><li>Choose a Custom Room Name</li><li>Play against Ranked Bot</li></ul><h3 id="diamond-pickaxe" tabindex="-1">Diamond Pickaxe <a class="header-anchor" href="#diamond-pickaxe" aria-label="Permalink to &quot;Diamond Pickaxe&quot;">​</a></h3><ul><li>Same as Iron Pickaxe</li><li>Request to Join Private Room option</li></ul><h2 id="rng-standardization" tabindex="-1">RNG Standardization <a class="header-anchor" href="#rng-standardization" aria-label="Permalink to &quot;RNG Standardization&quot;">​</a></h2><p>The standardizations listed below are relevant for some of the categories that can be chosen in a private room, see <a href="./rng">here</a> for the full list of standardizations.</p><ul><li>Rain/thunderstorm cycle is standardized <ul><li>Also thunderstorms are more frequent</li></ul></li><li>Phantoms spawn and cycle are standardized</li></ul>',16)])])}const u=e(t,[["render",l]]);export{p as __pageData,u as default};
